"""Core backend implementations for dataforge."""


class Backend:
    """Base class for execution backends."""

    name = "base"

    def __init__(self, compiled=False):
        self.compiled = compiled

    def execute(self, steps):
        """Execute a sequence of pipeline steps and return the result."""
        raise NotImplementedError

    def __repr__(self):
        return "{}(compiled={!r})".format(type(self).__name__, self.compiled)


class NativeBackend(Backend):
    """A native, in-process execution backend.

    When ``compiled=True`` the backend simulates ahead-of-time compilation of
    the pipeline steps before executing them.
    """

    name = "native"

    def __init__(self, compiled=False):
        super().__init__(compiled=compiled)
        self._compiled_steps = None

    def compile(self, steps):
        self._compiled_steps = list(steps)
        return self._compiled_steps

    def execute(self, steps):
        steps = list(steps)
        if self.compiled:
            steps = self.compile(steps)
        result = 0
        for step in steps:
            result = step(result)
        return result

"""Pipeline orchestration for dataforge."""


class Pipeline:
    """A simple data pipeline executed on a given backend."""

    def __init__(self, backend, steps=None):
        if backend is None:
            raise ValueError("Pipeline requires a backend")
        self.backend = backend
        self.steps = list(steps) if steps is not None else self._default_steps()

    @staticmethod
    def _default_steps():
        # A trivial pipeline: increment, double, then add ten.
        return [
            lambda x: x + 1,
            lambda x: x * 2,
            lambda x: x + 10,
        ]

    def run(self):
        """Run the pipeline on the configured backend and return the result."""
        result = self.backend.execute(self.steps)
        return "Pipeline completed on {} backend (compiled={}): result={}".format(
            self.backend.name, self.backend.compiled, result
        )

